function isRotatedSorted(nums: number[]): boolean {
  const n = nums.length;
  for (let s = 0; s < n; s++) {
    let ok = true;
    for (let i = 0; i + 1 < n && ok; i++) {
      if (nums[(s + i) % n] > nums[(s + i + 1) % n]) ok = false;
    }
    if (ok) return true;
  }
  return false;
}

